class BatchGeometryCreator:
    """Batch geometry creation for improved performance."""

    def __init__(self, model_space):
        self.model_space = model_space
        self.batch_size = 50
        self.operations = []

    def add_circle_batch(self, circles_data):
        """Batch create multiple circles."""
        for center, radius in circles_data:
            self.operations.append(('circle', center, radius))

            # Execute batch when limit reached
            if len(self.operations) >= self.batch_size:
                self.execute_batch()

    def execute_batch(self):
        """Execute all batched operations."""
        if not self.operations:
            return

        try:
            # Group by operation type for efficiency
            circles = [(center, radius) for op, center, radius in self.operations if op == 'circle']

            # Execute circles in batch
            for center, radius in circles:
                center_variant = convert_to_variant_array(center)
                self.model_space.AddCircle(center_variant, radius)

            self.operations.clear()

        except Exception as e:
            print(f"Batch execution failed: {e}")
            # Fallback to individual execution
            self.execute_individual()

    def execute_individual(self):
        """Fallback to individual execution."""
        for operation in self.operations:
            try:
                op_type, *params = operation
                if op_type == 'circle':
                    self.create_circle_individual(*params)
            except Exception as e:
                print(f"Individual operation failed: {e}")

        self.operations.clear()


class AutoCADObjectCache:
    """Cache frequently used AutoCAD objects and references."""

    def __init__(self):
        self._model_space = None
        self._active_document = None
        self._layers = {}
        self._last_access = {}

    @property
    def model_space(self):
        """Get cached model space reference."""
        if self._model_space is None:
            self._model_space = self.active_document.ModelSpace
        return self._model_space

    @property
    def active_document(self):
        """Get cached active document reference."""
        if self._active_document is None:
            self._active_document = acad_app.ActiveDocument
        return self._active_document

    def get_layer(self, layer_name):
        """Get cached layer reference."""
        if layer_name not in self._layers:
            # Try to get existing layer
            try:
                self._layers[layer_name] = self.active_document.Layers.Item(layer_name)
            except:
                # Create new layer if it doesn't exist
                self._layers[layer_name] = self.active_document.Layers.Add(layer_name)

        return self._layers[layer_name]

    def invalidate_cache(self):
        """Clear cache when document changes."""
        self._model_space = None
        self._active_document = None
        self._layers.clear()
        self._last_access.clear()

# Global cache instance
object_cache = AutoCADObjectCache()


class LazyGeometryProcessor:
    """Process geometry with lazy evaluation."""

    def __init__(self, geometry_data):
        self._geometry_data = geometry_data
        self._processed_geometry = None
        self._validation_result = None

    @property
    def processed_geometry(self):
        """Get processed geometry, computing only when needed."""
        if self._processed_geometry is None:
            self._processed_geometry = self._process_geometry()
        return self._processed_geometry

    @property
    def is_valid(self):
        """Check if geometry is valid, computing only when needed."""
        if self._validation_result is None:
            self._validation_result = self._validate_geometry()
        return self._validation_result

    def _process_geometry(self):
        """Expensive geometry processing operation."""
        # Complex coordinate transformations, validation, etc.
        processed = []
        for item in self._geometry_data:
            # Expensive processing here
            processed_item = self._transform_coordinates(item)
            processed.append(processed_item)
        return processed

    def _validate_geometry(self):
        """Expensive validation operation."""
        # Comprehensive validation logic
        for item in self._geometry_data:
            if not self._is_valid_item(item):
                return False
        return True

import gc import psutil import os
class MemoryManager: """Manage memory usage during AutoCAD operations."""
def __init__(self, memory_threshold_mb=500): self.memory_threshold_mb = memory_threshold_mb self.initial_memory = self.get_memory_usage()
def get_memory_usage(self): """Get current memory usage in MB.""" process = psutil.Process(os.getpid()) return process.memory_info().rss / 1024 / 1024
def should_cleanup(self): """Check if memory cleanup is needed.""" current_memory = self.get_memory_usage() memory_increase = current_memory - self.initial_memory return memory_increase > self.memory_threshold_mb
def cleanup_memory(self): """Perform memory cleanup operations.""" # Force garbage collection gc.collect()
# Clear any cached objects that can be recreated if hasattr(object_cache, 'invalidate_cache'): object_cache.invalidate_cache()
# Log memory cleanup current_memory = self.get_memory_usage() print(f"Memory cleanup completed. Current usage: {current_memory:.1f} MB")
def monitor_operation(self, operation_func, *args, **kwargs): """Monitor memory usage during operation.""" start_memory = self.get_memory_usage()
try: result = operation_func(*args, **kwargs) return result finally: end_memory = self.get_memory_usage() memory_delta = end_memory - start_memory
if memory_delta > 50: # Log significant memory increases print(f"Operation memory delta: +{memory_delta:.1f} MB")
if self.should_cleanup(): self.cleanup_memory()
# Usage memory_manager = MemoryManager()
def monitored_create_geometry(geometry_data): """Create geometry with memory monitoring.""" return memory_manager.monitor_operation( create_geometry_batch, geometry_data )

