import time
import functools
from collections import defaultdict

class AutoCADProfiler:
    """Profile AutoCAD operations for performance analysis."""

    def __init__(self):
        self.operation_times = defaultdict(list)
        self.operation_counts = defaultdict(int)

    def profile_operation(self, operation_name):
        """Decorator to profile operation execution time."""
        def decorator(func):
            @functools.wraps(func)
            def wrapper(*args, **kwargs):
                start_time = time.perf_counter()
                try:
                    result = func(*args, **kwargs)
                    return result
                finally:
                    end_time = time.perf_counter()
                    execution_time = end_time - start_time

                    self.operation_times[operation_name].append(execution_time)
                    self.operation_counts[operation_name] += 1

                    if execution_time > 1.0:  # Log slow operations
                        print(f"SLOW OPERATION: {operation_name} took {execution_time:.3f}s")
            return wrapper
        return decorator

    def get_performance_report(self):
        """Generate performance report."""
        report = []
        report.append("AutoCAD Performance Report")
        report.append("=" * 40)

        for operation, times in self.operation_times.items():
            count = self.operation_counts[operation]
            avg_time = sum(times) / len(times)
            max_time = max(times)
            total_time = sum(times)

            report.append(f"\nOperation: {operation}")
            report.append(f"  Count: {count}")
            report.append(f"  Average: {avg_time:.3f}s")
            report.append(f"  Maximum: {max_time:.3f}s")
            report.append(f"  Total: {total_time:.3f}s")

        return "\n".join(report)

# Global profiler instance
profiler = AutoCADProfiler()

@profiler.profile_operation("create_circle")
def create_circle_profiled(center, radius):
    """Profile circle creation."""
    return create_circle(center, radius)

@profiler.profile_operation("create_line")
def create_line_profiled(start, end):
    """Profile line creation."""
    return create_line(start, end)


class ProgressTracker:
    """Track progress of long-running AutoCAD operations."""

    def __init__(self, total_operations, description="Processing"):
        self.total_operations = total_operations
        self.completed_operations = 0
        self.description = description
        self.start_time = time.time()

    def update_progress(self, increment=1):
        """Update progress and display status."""
        self.completed_operations += increment
        progress_percent = (self.completed_operations / self.total_operations) * 100

        # Calculate estimated time remaining
        elapsed_time = time.time() - self.start_time
        if self.completed_operations > 0:
            avg_time_per_op = elapsed_time / self.completed_operations
            remaining_ops = self.total_operations - self.completed_operations
            estimated_remaining = remaining_ops * avg_time_per_op

            print(f"{self.description}: {self.completed_operations}/{self.total_operations} "
                  f"({progress_percent:.1f}%) - Est. remaining: {estimated_remaining:.1f}s")
        else:
            print(f"{self.description}: {self.completed_operations}/{self.total_operations} "
                  f"({progress_percent:.1f}%)")

    def is_complete(self):
        """Check if all operations are complete."""
        return self.completed_operations >= self.total_operations

    def get_completion_time(self):
        """Get total completion time."""
        return time.time() - self.start_time

# Usage example
def create_stair_components_batch(component_data):
    """Create stair components with progress tracking."""
    tracker = ProgressTracker(len(component_data), "Creating stair components")

    for i, (component_type, params) in enumerate(component_data):
        if component_type == "tread":
            create_tread(*params)
        elif component_type == "picket":
            create_picket(*params)
        elif component_type == "handrail":
            create_handrail(*params)

        tracker.update_progress()

        # Periodic memory cleanup
        if i % 25 == 0:
            memory_manager.cleanup_memory()

    print(f"Completed in {tracker.get_completion_time():.2f} seconds")
    return tracker.is_complete()
